#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    int size = 1 << n;
    vector<char> reachable(size, 0);
    for (int i = 0; i < k; i++) { int x; scanf("%d", &x); reachable[x] = 1; }
    // Superset propagation: a mask is reachable if some input is its submask.
    for (int step = 1; step < size; step <<= 1)
        for (int base = 0; base < size; base += 2 * step)
            for (int low = base; low < base + step; low++)
                if (reachable[low]) reachable[low + step] = 1;
    long long total = 0;
    for (char c : reachable) total += c;
    printf("%lld\n", total);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int size = 1 << n;
        boolean[] reachable = new boolean[size];
        for (int i = 0; i < k; i++) reachable[nextInt()] = true;
        // Superset propagation: a mask is reachable if some input is its submask.
        for (int step = 1; step < size; step <<= 1)
            for (int base = 0; base < size; base += 2 * step)
                for (int low = base; low < base + step; low++)
                    if (reachable[low]) reachable[low + step] = true;
        long total = 0;
        for (boolean r : reachable) if (r) total++;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, k := readInt(), readInt()
	size := 1 << n
	reachable := make([]bool, size)
	for i := 0; i < k; i++ {
		reachable[readInt()] = true
	}
	// Superset propagation: a mask is reachable if some input is its submask.
	for step := 1; step < size; step <<= 1 {
		for base := 0; base < size; base += 2 * step {
			for low := base; low < base+step; low++ {
				if reachable[low] {
					reachable[low+step] = true
				}
			}
		}
	}
	total := 0
	for _, r := range reachable {
		if r {
			total++
		}
	}
	fmt.Println(total)
}
